package com.lyrashop.user.entity;import java.util.UUID;import org.hibernate.annotations.JdbcTypeCode;import org.hibernate.type.SqlTypes;import jakarta.persistence.*;
@Entity @Table(name="payment_methods") public class PaymentMethodToken{@Id @GeneratedValue(strategy=GenerationType.UUID)@JdbcTypeCode(SqlTypes.BINARY)@Column(length=16)private UUID id;@JdbcTypeCode(SqlTypes.BINARY)@Column(name="user_id",length=16)private UUID userId;private String provider;@Column(name="provider_token")private String providerToken;@Column(name="display_name")private String displayName;@Column(name="last_four")private String lastFour;@Column(name="is_default")private boolean defaultMethod;protected PaymentMethodToken(){}public PaymentMethodToken(UUID u,String p,String t,String d,String l){userId=u;provider=p;providerToken=t;displayName=d;lastFour=l;}public UUID getId(){return id;}public String getProvider(){return provider;}public String getDisplayName(){return displayName;}public String getLastFour(){return lastFour;}public boolean isDefaultMethod(){return defaultMethod;}public void setDefault(boolean v){defaultMethod=v;}}
